// Mail-Assistent (ALLY 28, BA5, Stefan 19.10.2026): M1 Überblick (offene Antwortvorschläge, neue Mails der Kundschaft 24 h, aktive Postfächer, Fehler), danach aufklappbar (M2):
// Antwortvorschläge, Neue Mail, Finden, Mail-Log. Daten wie ALLY 8 (arbeit_web_seite 'mails'). Formulare mit den Feldern von ALLY 8 (entwurf, ablehnen, neue_mail).
// Liefert nur die Seitenbeschreibung (JSON).
const E = $('Start').first().json;
const D = $input.first().json || {};
const F = E.funktion || {};
const P = E.parameter || {};
const titel = String(F.name || 'Mail-Assistent');
const kopf = { schluessel: 'mail-assistent', art: 'funktion', titel, beschreibung: String(F.beschreibung || ''), krumen: [{ text: 'Startseite', ziel: { seite: 'start' } }, { text: titel }] };
if (/^[a-z0-9-]{1,40}$/.test(String(F.einstellungen_ziel || ''))) kopf.zahnrad = { ziel: { seite: 'einstellungen', parameter: { bereich: String(F.einstellungen_ziel) } } };
const V = D.v || null;
if (D.ok !== true || !V) return [{ json: { inhalt: { seite: kopf, bloecke: [{ typ: 'hinweis', ton: 'warn', text: 'Die Mails konnten nicht geladen werden. Bitte die Seite neu laden.' }] } } }];
const ZU = D.zustand || {};
const entw = V.entwuerfe === true;
const angebote = Array.isArray(V.angebote) ? V.angebote : [];
const pf = Array.isArray(D.pf) ? D.pf : [];
const aktivePf = pf.filter(p => p.aktiv);
const fehlerPf = pf.filter(p => p.aktiv && p.eingerichtet && p.ergebnis && p.ergebnis !== 'ok');
const neu24 = ((D.l24 || {}).log || []).length;
const hier = (extra, anker) => ({ seite: 'mail-assistent', parameter: Object.assign({}, ['fq', 'ft', 'lq', 'lt', 'lk'].reduce((o, k) => (P[k] ? Object.assign(o, { [k]: P[k] }) : o), {}), extra || {}), anker });
const ueberblick = { kennzahlen: [
  { label: 'Antwortvorschläge offen', wert: entw ? String(angebote.length) + (angebote.length >= 30 ? '+' : '') : '–', neben: entw ? 'letzte 14 Tage' : '', ziel: entw ? hier({}, 'a-vorschlaege') : undefined },
  { label: 'Neue Mails der Kundschaft 24 h', wert: String(neu24), neben: '' },
  { label: 'Aktive Postfächer', wert: String(aktivePf.length), neben: pf.length - aktivePf.length ? (pf.length - aktivePf.length) + ' pausiert' : '' },
  { label: 'Fehler', wert: String(fehlerPf.length), neben: fehlerPf.length ? 'Zugang prüfen' : '', ton: fehlerPf.length ? 'warn' : '' }].map(k => { if (!k.ziel) delete k.ziel; return k; }),
  karten: [
    { titel: 'Offen', leer: 'Nichts offen.', eintraege: angebote.slice(0, 5).map(m => ({ marke: { text: 'Vorschlag' }, text: String(m.betreff || '(ohne Betreff)'), neben: String(m.absender || ''),
      ziel: hier({ mail: m.id, quelle: 'v' }, 'a-vorschlaege'), ziel_text: 'Öffnen' })) },
    { titel: 'Meldungen', leer: 'Keine Meldungen.', eintraege: fehlerPf.map(p => ({ marke: { text: 'Fehler', ton: 'warn' }, text: p.adresse + ': ' + String(p.ergebnis || ''), neben: p.geprueft ? 'geprüft ' + p.geprueft : '' }))
      .concat(pf.filter(p => p.aktiv && !p.eingerichtet).map(p => ({ marke: { text: 'offen', ton: 'grau' }, text: p.adresse + ': Zugang nicht eingerichtet' }))) }] };

// Sortierung und Seiten (je Person gemerkt)
const sortierung = (tab, erlaubt, std, stdR) => { const s = (ZU['mail-assistent.' + tab] || {}).sortierung || {};
  return { spalte: erlaubt.includes(s.spalte) ? s.spalte : std, richtung: s.richtung === 'auf' || s.richtung === 'ab' ? s.richtung : stdR }; };
const zeit = s => { const m = /^(\d{2})\.(\d{2})\.(\d{4})\s+(\d{2}):(\d{2})/.exec(String(s || '')); return m ? m[3] + m[2] + m[1] + m[4] + m[5] : ''; };
const sortiere = (zeilen, so, wert) => zeilen.map((z, i) => [z, i]).sort((a, b) => { const x = wert(a[0], so.spalte), y = wert(b[0], so.spalte);
  const c = String(x ?? '').localeCompare(String(y ?? ''), 'de'); return (so.richtung === 'ab' ? -c : c) || a[1] - b[1]; }).map(x => x[0]);
// Layout 10 (Plan 37, Koordinator 24.10.2026, E8/E10): 10 je Seite wie die Anzeige – „Alle markieren“ zählt dann genau die sichtbare Seite
const JE = 10;
const blatt = (tab, n) => { const s = Math.max(1, Number((E.seiten || {})[tab]) || 1); return Math.min(s, Math.max(1, Math.ceil(n / JE))); };
const wertMail = (m, sp) => sp === 'eingang' ? zeit(m.eingang) : String(m[sp] || '').toLowerCase();
const STAND = { gespeichert: ['gespeichert', 'grau'], offen: ['Vorschlag offen', 'warn'], entwurf: ['Entwurf erstellt', 'ok'], abgelehnt: ['kein Entwurf', 'grau'] };
const mailTabelle = (id, liste, mitStand, quelle) => {
  const so = sortierung(id, ['betreff', 'absender', 'eingang', 'postfach', 'status'], 'eingang', 'ab');
  const sortiert = sortiere(liste.slice(), so, wertMail), bl = blatt(id, sortiert.length);
  const sp = [{ schluessel: 'betreff', titel: 'Betreff', sortierbar: true }, { schluessel: 'absender', titel: 'Von', sortierbar: true }, { schluessel: 'eingang', titel: 'Eingang', sortierbar: true },
    mitStand ? { schluessel: 'status', titel: 'Stand', sortierbar: true } : { schluessel: 'postfach', titel: 'Postfach', sortierbar: true }];
  return { typ: 'tabelle', id, titel: id === 'vorschlaege' ? 'Antwortvorschläge' : 'Gefundene Mails', spalten: sp,
    zeilen: sortiert.slice((bl - 1) * JE, bl * JE).map(m => { const st = STAND[m.status] || [String(m.status || ''), 'grau'];
      return { aktiv: String(P.mail || '') === String(m.id) && P.quelle === quelle, zellen: { betreff: { text: String(m.betreff || '(ohne Betreff)'), ziel: hier({ mail: m.id, quelle }, 'a-' + id) },
        absender: String(m.absender || ''), eingang: String(m.eingang || ''), postfach: String(m.postfach || ''), status: { marke: { text: st[0], ton: st[1] } } } }; }),
    sortierung: so, seite: bl, je_seite: JE, gesamt: sortiert.length, leer: id === 'vorschlaege' ? 'Keine offenen Antwortvorschläge.' : 'Keine Mail gefunden.' };
};
const entwurfForm = (m, id) => ({ typ: 'formular', id, aktion: 'entwurf', werte: { id: m.id }, felder: [{ typ: 'textbereich', name: 'anweisung', label: 'Stichpunkte für die Antwort', zeilen: 4, breite: 'voll', hinweis: 'Leer lassen für eine passende Antwort.' }],
  frage: 'Antwortentwurf erstellen? Er wird nur im Entwürfe-Ordner abgelegt, nicht verschickt.', knoepfe: [{ text: 'Entwurf erstellen' }] });
const abschnitte = [], fenster = [];
if (entw) {
  abschnitte.push({ id: 'vorschlaege', titel: 'Antwortvorschläge', zahl: String(angebote.length), offen_standard: true, inhalt: [mailTabelle('vorschlaege', angebote, false, 'v')] });
  if (aktivePf.length) fenster.push({ id: 'neu', art: 'dialog', titel: 'Neue Mail', inhalt: [{ typ: 'formular', id: 'neue-mail', aktion: 'neue_mail', spalten: 2,
    frage: 'Neue Mail als Entwurf anlegen? Sie wird nicht verschickt.', felder: [
      { typ: 'auswahl', name: 'postfach', label: 'Postfach', wert: aktivePf.some(p => p.adresse === V.standard) ? V.standard : aktivePf[0].adresse, optionen: aktivePf.map(p => ({ wert: p.adresse, text: p.adresse })), breite: 'voll' },
      { typ: 'email', name: 'an', label: 'An', autocomplete: 'off' }, { typ: 'text', name: 'an_name', label: 'Name', autocomplete: 'off' },
      { typ: 'text', name: 'betreff', label: 'Betreff', pflicht: true, breite: 'voll' }, { typ: 'textbereich', name: 'anweisung', label: 'Inhalt oder Stichpunkte', pflicht: true, zeilen: 6, breite: 'voll' }],
    knoepfe: [{ text: 'Abbrechen', art: 'neben', schliesst: true }, { text: 'Entwurf erstellen' }] }] });
  const tr = (D.f || {}).treffer;
  abschnitte.push({ id: 'finden', titel: 'Finden', zahl: Array.isArray(tr) ? String(tr.length) : '', offen_standard: !!P.fq, inhalt: [
    { typ: 'filter', id: 'finden', label: 'Mails finden', felder: [{ typ: 'suche', name: 'fq', label: 'Suchbegriff', platzhalter: 'Name, Firma, Domain, Betreff', wert: String(P.fq || '') },
      { typ: 'auswahl', name: 'ft', label: 'Zeitraum', wert: String((D.f || {}).tage || P.ft || '14'), optionen: [{ wert: '7', text: '7 Tage' }, { wert: '14', text: '14 Tage' }, { wert: '30', text: '30 Tage' }] }] }]
    .concat(Array.isArray(tr) ? [mailTabelle('finden', tr, true, 'f')] : []) });
  const sel = P.quelle === 'v' ? angebote.find(m => String(m.id) === String(P.mail)) : P.quelle === 'f' && Array.isArray(tr) ? tr.find(m => String(m.id) === String(P.mail)) : null;
  if (sel) fenster.push({ id: 'mail', art: 'seitenfenster', offen: true, titel: String(sel.betreff || '(ohne Betreff)'), untertitel: String(sel.absender || ''),
    schliessen_ziel: hier({}, P.quelle === 'v' ? 'a-vorschlaege' : 'a-finden'), inhalt: [
      { typ: 'paare', eintraege: [{ label: 'Von', wert: String(sel.absender || '') }, { label: 'Eingang', wert: String(sel.eingang || '') }, { label: 'Postfach', wert: String(sel.postfach || '') }] },
      { typ: 'text', text: String(sel.zusammenfassung || sel.auszug || '') }, entwurfForm(sel, 'entwurf')]
      .concat(P.quelle === 'v' ? [{ typ: 'aktion', text: 'Kein Entwurf', aktion: 'ablehnen', werte: { id: sel.id }, frage: 'Kein Entwurf zu dieser Mail?' }] : []) });
}
const KAT = [['', 'Alle Kategorien'], ['kunde', 'Kundschaft'], ['geschaeft', 'Geschäftlich'], ['keine', 'Keine Einordnung'], ['spam', 'Spam'], ['system_report', 'System-Report']];
const log = (D.l || {}).log || [];
const soL = sortierung('log', ['zeit', 'betreff', 'kategorie'], 'zeit', 'ab');
const logS = sortiere(log.slice(), soL, (l, sp) => sp === 'zeit' ? zeit(l.zeit) : String(l[sp] || '').toLowerCase()), blL = blatt('log', logS.length);
abschnitte.push({ id: 'log', titel: 'Mail-Log', zahl: String(log.length) + (log.length >= 100 ? '+' : ''), offen_standard: !entw, inhalt: [
  { typ: 'filter', id: 'log', label: 'Mail-Log filtern', felder: [{ typ: 'auswahl', name: 'lk', label: 'Kategorie', wert: String(P.lk || ''), optionen: KAT.map(([w, t]) => ({ wert: w, text: t })) },
    { typ: 'auswahl', name: 'lt', label: 'Zeitraum', wert: String((D.l || {}).tage || '14'), optionen: [{ wert: '1', text: 'heute und gestern' }, { wert: '7', text: '7 Tage' }, { wert: '14', text: '14 Tage' }, { wert: '30', text: '30 Tage' }] },
    { typ: 'suche', name: 'lq', label: 'Suchbegriff', wert: String(P.lq || '') }] },
  { typ: 'tabelle', id: 'log', titel: 'Mail-Log', spalten: [{ schluessel: 'zeit', titel: 'Zeit', sortierbar: true }, { schluessel: 'betreff', titel: 'Betreff', sortierbar: true }, { schluessel: 'kategorie', titel: 'Einordnung', sortierbar: true }],
    zeilen: logS.slice((blL - 1) * JE, blL * JE).map(l => ({ zellen: { zeit: String(l.zeit || ''), betreff: { text: String(l.betreff || '(ohne Betreff)'), neben: [l.absender, l.postfach].filter(Boolean).join(' · ') },
      kategorie: { text: (KAT.find(k => k[0] === l.kategorie) || [0, String(l.kategorie || '')])[1], neben: String(l.begruendung || '') } } })),
    sortierung: soL, seite: blL, je_seite: JE, gesamt: logS.length, leer: 'Keine Einträge.' }] });
if (entw && aktivePf.length) kopf.hauptaktion = { text: 'Neue Mail', fenster: 'neu' };
return [{ json: { inhalt: { seite: kopf, ueberblick, abschnitte, fenster } } }];

// Parameter (ALLY 28, Mail-Assistent): Sitzung; Finden (fq Suchbegriff, ft Tage), Mail-Log (lq, lt, lk Kategorie). Tage 1–30, Texte bis 100 Zeichen ohne Steuerzeichen.
const E = $input.first().json;
const P = E.parameter || {};
const txt = v => String(v || '').replace(/[\x00-\x1f\x7f]/g, ' ').trim().slice(0, 100);
const tage = (v, std) => /^[0-9]{1,2}$/.test(String(v || '')) ? String(Math.min(30, Math.max(1, Number(v)))) : std;
const lk = ['kunde', 'geschaeft', 'keine', 'spam', 'system_report'].includes(String(P.lk || '')) ? String(P.lk) : '';
return [{ json: { werte: [/^[0-9a-f]{64}$/.test(String(E.sitzung || '')) ? String(E.sitzung) : '', txt(P.fq), tage(P.ft, '14'), txt(P.lq), tage(P.lt, '14'), lk] } }];
